@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* View transitions: directional page slides */

@keyframes slide-in-from-right {
  from {
    transform: translateX(60px);
    opacity: 0;
  }
}

@keyframes slide-out-to-right {
  to {
    transform: translateX(60px);
    opacity: 0;
  }
}

@keyframes slide-in-from-left {
  from {
    transform: translateX(-60px);
    opacity: 0;
  }
}

@keyframes slide-out-to-left {
  to {
    transform: translateX(-60px);
    opacity: 0;
  }
}

::view-transition-new(.page-from-right):only-child {
  animation: slide-in-from-right 300ms cubic-bezier(0.4, 0, 0.2, 1) both;
}

::view-transition-old(.page-to-right):only-child {
  animation: slide-out-to-right 300ms cubic-bezier(0.4, 0, 0.2, 1) both;
}

::view-transition-new(.page-from-left):only-child {
  animation: slide-in-from-left 300ms cubic-bezier(0.4, 0, 0.2, 1) both;
}

::view-transition-old(.page-to-left):only-child {
  animation: slide-out-to-left 300ms cubic-bezier(0.4, 0, 0.2, 1) both;
}

/* View transitions: shared-element morph between thumbnail and hero image */

::view-transition-group(.product-morph) {
  animation-duration: 350ms;
  animation-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
}

/* View transitions: Suspense skeleton-to-content cross-fade */

::view-transition-old(.suspense-reveal),
::view-transition-new(.suspense-reveal) {
  animation-duration: 250ms;
  animation-timing-function: ease;
}

/* Respect reduced-motion: skip all view-transition animation and skeleton pulse */

@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(*),
  ::view-transition-image-pair(*),
  ::view-transition-old(*),
  ::view-transition-new(*) {
    animation: none !important;
  }

  .skeleton-image,
  .skeleton-text {
    animation: none;
  }
}

